fn solve(n: i8, s: Vec<char>) -> i8 {
    // If there's fewer than 2 characters, there are no adjacent pairs to compare.
    if n < 2 {
        return 0;
    }

    let mut count: i8 = 0;
    // We know n >= 2, so (n - 1) is non-negative and fits in usize when cast.
    let limit = (n - 1) as usize;
    for i in 0..limit {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }

    count
}

